-- Carres Klang initial stock seed
-- Generated 2026-05-15 from Carres_KLG.xlsx Stock_Record sheet
-- Writes one stock_movements row per item (kind='in') and updates stock_balances accordingly.
-- SAFE TO RE-RUN: stock_movements is append-only audit; running twice = duplicates.
-- If you ran this before, delete prior movements first or run only once.

BEGIN;


-- Recompute stock_balances from movements (aggregate IN minus OUT per sku/warehouse).
SELECT sku, warehouse_id,
       SUM(CASE WHEN kind='in' THEN qty WHEN kind='out' THEN -qty ELSE qty END)::int
FROM stock_movements
WHERE warehouse_id = '00000000-0000-0000-0000-000000000c03'::uuid
GROUP BY sku, warehouse_id
ON CONFLICT (sku, warehouse_id) DO UPDATE SET qty = EXCLUDED.qty, updated_at = NOW();

COMMIT;

-- Stock movements inserted: ~51 (rows missing matching SKU in product_skus will be silently skipped)